import { FeatureDefinition, FeatureCategory, PipelineStage } from "../types/index.js";

/**
 * FeatureRegistry is the single source of truth for every field generated by LexForge.
 */
export class FeatureRegistry {
  private static features = new Map<string, FeatureDefinition>();

  /**
   * Registers a new feature.
   * Throws if the feature ID already exists.
   */
  static register(feature: FeatureDefinition): void {
    if (this.features.has(feature.id)) {
      throw new Error(`Feature with ID '${feature.id}' is already registered.`);
    }

    // Validate that no other feature outputs the same fields
    for (const existingFeature of this.features.values()) {
      for (const field of feature.outputFields) {
        if (existingFeature.outputFields.includes(field)) {
          throw new Error(`Feature '${feature.id}' attempts to output field '${field}', which is already owned by '${existingFeature.id}'.`);
        }
      }
    }

    this.features.set(feature.id, feature);
  }

  static getAll(): FeatureDefinition[] {
    return Array.from(this.features.values());
  }

  static getByCategory(category: FeatureCategory): FeatureDefinition[] {
    return this.getAll().filter((f) => f.category === category);
  }

  static getByStage(stage: PipelineStage): FeatureDefinition[] {
    return this.getAll().filter((f) => f.stage === stage);
  }

  static getById(id: string): FeatureDefinition | undefined {
    return this.features.get(id);
  }

  /**
   * Clears the registry (useful for testing).
   */
  static clear(): void {
    this.features.clear();
  }
}

// Pre-register existing features to maintain the single source of truth
